window.VO = [{"id":"n01","text":"You've got one second.","at":0.24,"t0":0.12,"t1":1.575},{"id":"n02","text":"One man here killed someone.","at":3.31,"t0":1.655,"t1":3.473},{"id":"n03","text":"Pick him.","at":7.186,"t0":3.593,"t1":4.32},{"id":"n04","text":"Got a number? Now, which one do you trust with your house keys?","at":10.14,"t0":5.07,"t1":9.797},{"id":"n05","text":"Number one? He won't even look at you.","at":20.494,"t0":10.247,"t1":13.156},{"id":"n06","text":"Number two? He can't stop smiling.","at":26.812,"t0":13.406,"t1":15.588},{"id":"n07","text":"Number three hasn't blinked.","at":31.676,"t0":15.838,"t1":17.293},{"id":"n08","text":"And number four looks sorry. For what?","at":35.086,"t0":17.543,"t1":20.088},{"id":"n09","text":"You've got one second. Pick him.","at":41.076,"t0":20.538,"t1":22.72},{"id":"n10","text":"That's one killer, and one man you trust with your house.","at":47.14,"t0":23.57,"t1":27.57},{"id":"n11","text":"It's the same man.","at":56.14,"t0":28.07,"t1":29.525},{"id":"n12","text":"I did say one man.","at":62.15,"t0":31.075,"t1":32.893},{"id":"n13","text":"Look at the cut in his eyebrow. It's in all four photos.","at":66.586,"t0":33.293,"t1":37.657},{"id":"n14","text":"You stared at him for twenty-four seconds and never noticed.","at":76.012,"t0":38.006,"t1":41.642},{"id":"n15","text":"Your brain decided in a tenth of a second, and then I handed you four reasons.","at":83.986,"t0":41.993,"t1":47.811},{"id":"n16","text":"You never judged him. You judged a photo.","at":96.422,"t0":48.211,"t1":51.12},{"id":"n17","text":"Everyone's got a villain photo. Yours is on your Aadhaar.","at":103.04,"t0":51.52,"t1":55.156},{"id":"n18","text":"And he's still got your keys.","at":111.512,"t0":55.756,"t1":57.938}];
